SELECT no_plan();
CREATE TEMP TABLE f AS SELECT id,vehicle_id FROM bookings WHERE reservation_number='ZNX-000150';
UPDATE vehicles SET is_active=true,availability_status='active',minimum_rental_hours=1 WHERE id=(SELECT vehicle_id FROM f);
UPDATE bookings SET archived_at=now() WHERE vehicle_id=(SELECT vehicle_id FROM f);
DELETE FROM vehicle_blocked_periods WHERE vehicle_id=(SELECT vehicle_id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),true,'same day two hours available');
SELECT ok(EXISTS(SELECT 1 FROM search_available_vehicles('2040-10-16','2040-10-16','10:00','12:00') WHERE id=(SELECT vehicle_id FROM f)),'search agrees');
SELECT is(validate_vehicle_rental_duration((SELECT vehicle_id FROM f),'2040-10-16','10:00','2040-10-16','12:00'),1,'duration agrees');
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','10:00'),false,'zero duration rejected');
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','12:00','10:00'),false,'reversed duration rejected');
SELECT is((SELECT count(*) FROM search_available_vehicles('2040-10-16','2040-10-16','12:00','10:00')),0::bigint,'search rejects reversed times');
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-17','23:00','01:00'),true,'overnight allowed');
UPDATE bookings SET archived_at=NULL,start_date='2040-10-16',end_date='2040-10-17',pickup_time='11:00',dropoff_time='10:00',trip_status='confirmed' WHERE id=(SELECT id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),false,'confirmed overlap protected');
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','09:00','11:00'),true,'adjacent boundary available');
UPDATE bookings SET archived_at=now() WHERE id=(SELECT id FROM f);
SELECT ok(EXISTS(SELECT 1 FROM search_available_vehicles('2040-10-16','2040-10-16','10:00','12:00') WHERE id=(SELECT vehicle_id FROM f)),'archived booking does not block search');
UPDATE bookings SET archived_at=NULL,trip_status='pending_payment',created_at=now() WHERE id=(SELECT id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),false,'fresh payment hold protected');
UPDATE bookings SET created_at=now()-interval '21 minutes' WHERE id=(SELECT id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),true,'expired hold available');
UPDATE vehicles SET is_active=false WHERE id=(SELECT vehicle_id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),false,'inactive protected');
UPDATE vehicles SET is_active=true WHERE id=(SELECT vehicle_id FROM f);
SELECT lives_ok($$UPDATE bookings SET start_date='2040-10-16',end_date='2040-10-16',pickup_time='10:00',dropoff_time='12:00' WHERE id=(SELECT id FROM f)$$,'persisted booking supports same day');
SELECT throws_like($$UPDATE bookings SET dropoff_time='09:00' WHERE id=(SELECT id FROM f)$$,'%minimum rental%','persisted reversed duration rejected');

UPDATE bookings SET trip_status='cancelled' WHERE id=(SELECT id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),true,'cancelled reservation does not block');
INSERT INTO vehicle_blocked_periods(vehicle_id,host_profile_id,start_at,end_at) SELECT id,host_profile_id,'2040-10-16 00:00+00','2040-10-17 00:00+00' FROM vehicles WHERE id=(SELECT vehicle_id FROM f);
SELECT is(check_vehicle_availability((SELECT vehicle_id FROM f),'2040-10-16','2040-10-16','10:00','12:00'),false,'explicit vehicle block protected');
